1	//! The application's theme (see the ThemeScope): a neutral grey interface
2	//! defined by its dark mode, around a base of #444444, with light mode read
3	//! from it. The palette here is the one source of every colour; gpui-kit's
4	//! theme is built from it, so components with default styling follow it, and
5	//! what draws its own colours asks for a role here.
6	
7	use std::rc::Rc;
8	
9	use gpui_kit::component::tag::{Tag, TagVariant};
10	use gpui_kit::component::{ActiveTheme as _, Theme, ThemeConfig, ThemeMode, ThemeRegistry};
11	use gpui_kit::*;
12	use serde_json::{Map, Value, json};
13	
14	/// Every role of the theme, for one mode, as 0xRRGGBB.
15	#[derive(Clone, Copy, Debug, PartialEq)]
16	pub struct Palette {
17	    /// Where content is read or written: the editor, code, answers.
18	    pub well: u32,
19	    /// Text inputs, lists, trees.
20	    pub recessed: u32,
21	    /// The window and its panels.
22	    pub base: u32,
23	    /// Buttons, tab bars, headers, cards.
24	    pub raised: u32,
25	    pub hover: u32,
26	    pub pressed: u32,
27	    /// A selected row or tab without focus.
28	    pub selected: u32,
29	    /// Menus, popovers, tooltips, inset panels.
30	    pub overlay: u32,
31	    /// The ribbon's command area, and its open tabs, which read as one piece
32	    /// with it.
33	    pub ribbon: u32,
34	    /// The ribbon's row of tabs, a step from its command area: lighter in dark
35	    /// mode, darker in light mode. Also the dividers between its groups.
36	    pub ribbon_tabs: u32,
37	    /// The darkest surface in dark mode, a step past the ribbon's command area
38	    /// away from its tab row: the project tree, and the commit message on the
39	    /// git panel. In light mode, a step lighter than the command area instead.
40	    pub darkest: u32,
41	    pub text: u32,
42	    /// What the spec calls muted.
43	    pub text_secondary: u32,
44	    /// Dimmer than muted: help text, placeholders.
45	    pub text_tertiary: u32,
46	    pub text_disabled: u32,
47	    /// Dividers between areas and rows.
48	    pub line: u32,
49	    /// The border of controls, inputs, and floating surfaces.
50	    pub edge: u32,
51	    /// Focus, selected tabs' underlines, links, accent text.
52	    pub accent: u32,
53	    /// Primary buttons, a selected item in a focused list.
54	    pub accent_fill: u32,
55	    pub success: u32,
56	    pub warning: u32,
57	    pub error: u32,
58	    pub purple: u32,
59	    pub cyan: u32,
60	    pub orange: u32,
61	    /// How much black dims the window behind a modal surface.
62	    pub dim: f32,
63	    /// How much white lights, and black shades, a bevel's edges.
64	    pub bevel_light: f32,
65	    pub bevel_shade: f32,
66	}
