69	    well: 0x2e2e2e,
70	    recessed: 0x383838,
71	    base: 0x444444,
72	    raised: 0x4e4e4e,
73	    hover: 0x585858,
74	    pressed: 0x3c3c3c,
75	    selected: 0x5e5e5e,
76	    overlay: 0x4a4a4a,
77	    // Two and one steps of 0x11 below the base, so the ribbon's buttons, at
78	    // the base, stand as far from its command area as its tab row, twice over.
79	    ribbon: 0x222222,
80	    ribbon_tabs: 0x333333,
81	    darkest: 0x111111,
82	    text: 0xebebeb,
83	    text_secondary: 0xc4c4c4,
84	    text_tertiary: 0x9c9c9c,
85	    text_disabled: 0x7a7a7a,
86	    line: 0x3a3a3a,
87	    edge: 0x2a2a2a,
88	    accent: 0x7fb4ea,
89	    accent_fill: 0x3d6a98,
90	    success: 0x8fd095,
91	    warning: 0xe6bb68,
92	    error: 0xf0928a,
93	    purple: 0xbba0e6,
94	    cyan: 0x78c8ce,
95	    orange: 0xf2a168,
96	    dim: 0.4,
97	    bevel_light: 0.08,
98	    bevel_shade: 0.06,
