118	    text_disabled: 0x8c8c8c,
119	    line: 0xbdbdbd,
120	    edge: 0xa6a6a6,
121	    accent: 0x1f5fa6,
122	    accent_fill: 0x2b68ad,
123	    success: 0x2c6e31,
124	    warning: 0x8a5a00,
125	    error: 0xb3261e,
126	    purple: 0x6b4aa6,
127	    cyan: 0x1f6f78,
128	    orange: 0x9a3f00,
129	    dim: 0.25,
130	    bevel_light: 0.55,
131	    bevel_shade: 0.03,
132	};
133	
134	/// How much of the accent fill selected text is laid over with.
135	const SELECTION_ALPHA: u8 = 0x59;
136	
137	pub const DARK_NAME: &str = "Suspense Dark";
138	pub const LIGHT_NAME: &str = "Suspense Light";
139	
140	/// The palette of the mode showing.
141	pub fn palette(cx: &App) -> &'static Palette {
142	    if cx.theme().is_dark() { &DARK } else { &LIGHT }
143	}
144	
145	/// `color` as an opaque colour.
146	pub fn color(color: u32) -> Hsla {
147	    rgb(color).into()
148	}
149	
150	/// A hue the spec names for what is shown, as the theme gives it.
151	#[derive(Clone, Copy, Debug, PartialEq, Eq)]
152	pub enum Hue {
153	    Blue,
154	    Cyan,
155	    Purple,
156	    Green,
157	    Amber,
158	    Orange,
159	    Red,
160	    Grey,
161	}
162	
163	impl Hue {
164	    pub fn of(self, palette: &Palette) -> Hsla {
165	        color(match self {
166	            Self::Blue => palette.accent,
167	            Self::Cyan => palette.cyan,
168	            Self::Purple => palette.purple,
169	            Self::Green => palette.success,
170	            Self::Amber => palette.warning,
171	            Self::Orange => palette.orange,
172	            Self::Red => palette.error,
173	            Self::Grey => palette.text_tertiary,
174	        })
175	    }
176	}
177	
178	/// A tag in `hue`: the hue's text over a faint tint of it, with a border of it.
179	pub fn tag(hue: Hue, cx: &App) -> Tag {
180	    let color = hue.of(palette(cx));
181	    Tag::new().with_variant(TagVariant::Custom {
182	        color: color.opacity(0.16),
183	        foreground: color,
184	        border: color.opacity(0.45),
185	    })
186	}
187	
188	/// How wide a bevel's edges are.
189	pub const BEVEL: Pixels = px(1.);
190	
191	/// Which way a bevel faces: raised, lit along its top and left, or pressed in,
192	/// the other way round.
193	#[derive(Clone, Copy, Debug, PartialEq, Eq)]
194	pub enum Bevel {
195	    Raised,
196	    Pressed,
197	}
198	
199	/// A bevel's lit and shaded edges' colours, laid over whatever they sit on.
200	pub fn bevel_colors(palette: &Palette) -> (Hsla, Hsla) {
201	    (
202	        white().opacity(palette.bevel_light),
203	        black().opacity(palette.bevel_shade),
204	    )
205	}
206	
207	/// The bevel of a surface at `bounds`, each edge with its colour. Raised, it is
208	/// lit along the top, then down the left beneath that, and shaded along the
209	/// bottom, then up the right above that, so no two overlap; pressed, the lit
210	/// and shaded edges swap. None for a surface too small.
211	pub fn bevel_edges(
212	    bounds: Bounds<Pixels>,
213	    bevel: Bevel,
214	    palette: &Palette,
215	) -> Vec<(Bounds<Pixels>, Hsla)> {
216	    let (width, height) = (bounds.size.width, bounds.size.height);
217	    if width < BEVEL * 2. || height < BEVEL * 2. {
218	        return Vec::new();
219	    }
220	    let (light, shade) = match (bevel, bevel_colors(palette)) {
221	        (Bevel::Raised, (light, shade)) => (light, shade),
222	        (Bevel::Pressed, (light, shade)) => (shade, light),
223	    };
224	    let side = height - BEVEL * 2.;
225	    vec![
226	        (Bounds::new(bounds.origin, size(width, BEVEL)), light),
227	        (
228	            Bounds::new(
229	                point(bounds.left(), bounds.top() + BEVEL),
230	                size(BEVEL, side),
231	            ),
232	            light,
233	        ),
234	        (
235	            Bounds::new(
236	                point(bounds.left(), bounds.bottom() - BEVEL),
237	                size(width, BEVEL),
238	            ),
239	            shade,
240	        ),
241	        (
242	            Bounds::new(
243	                point(bounds.right() - BEVEL, bounds.top() + BEVEL),
244	                size(BEVEL, side),
245	            ),
246	            shade,
247	        ),
248	    ]
249	}
250	
251	/// The bevel, laid over whatever positioned element it is put in, filling it
252	/// and taking no room or mouse.
253	pub fn bevel(bevel: Bevel, cx: &App) -> impl IntoElement {
254	    let palette = *palette(cx);
255	    canvas(
256	        |_, _, _| {},
257	        move |bounds, _, window, _| {
258	            for (edge, color) in bevel_edges(bounds, bevel, &palette) {
259	                window.paint_quad(fill(edge, color));
260	            }
261	        },
262	    )
263	    .absolute()
264	    .top_0()
265	    .left_0()
266	    .size_full()
267	}
268	
269	/// The black laid over the window behind a modal surface.
270	pub fn dimming(cx: &App) -> Hsla {
271	    black().opacity(palette(cx).dim)
272	}
273	
274	/// Registers the theme's two modes with gpui-kit and makes them the ones
275	/// light and dark mode show. Call after `gpui_kit::init`, before the theme
276	/// mode is chosen.
277	pub fn init(cx: &mut App) {
278	    let registry = ThemeRegistry::global(cx);
279	    let set = json!({
280	        "name": "Suspense",
281	        "themes": [
282	            config(&DARK, ThemeMode::Dark, registry.default_dark_theme()),
283	            config(&LIGHT, ThemeMode::Light, registry.default_light_theme()),
284	        ],
285	    });
286	    ThemeRegistry::global_mut(cx)
287	        .load_themes_from_str(&set.to_string())
288	        .expect("the theme's own configuration is valid");
289	    let themes = ThemeRegistry::global(cx).themes();
290	    let (dark, light) = (themes[DARK_NAME].clone(), themes[LIGHT_NAME].clone());
291	    let theme = Theme::global_mut(cx);
292	    theme.dark_theme = dark;
293	    theme.light_theme = light;
294	}
295	
296	fn hex(color: u32) -> String {
297	    format!("#{color:06x}")
298	}
299	
300	fn hex_alpha(color: u32, alpha: u8) -> String {
301	    format!("#{color:06x}{alpha:02x}")
302	}
