304	/// A gpui-kit theme for `palette`, keeping the syntax colours of `default`.
305	fn config(palette: &Palette, mode: ThemeMode, default: &Rc<ThemeConfig>) -> Value {
306	    let p = palette;
307	    let dark = mode.is_dark();
308	    // Text on a solid status or accent colour: dark over dark mode's light
309	    // hues, white over light mode's dark ones.
310	    let on_hue = if dark { hex(0x2a2a2a) } else { hex(0xffffff) };
311	    let (fill_hover, fill_active) = if dark {
312	        (0x4877a6, 0x335a82)
313	    } else {
314	        (0x3674ba, 0x245a96)
315	    };
316	    let dim = hex_alpha(0x000000, (p.dim * 255.).round() as u8);
317	
318	    let mut colors = Map::new();
319	    let mut set = |key: &str, value: String| {
320	        colors.insert(key.to_string(), Value::String(value));
321	    };
322	    set("background", hex(p.base));
323	    set("foreground", hex(p.text));
324	    set("border", hex(p.edge));
325	    set("input.border", hex(p.edge));
326	    set("window.border", hex(p.edge));
327	    set("caret", hex(p.text));
328	    set("ring", hex(p.accent));
329	    set("overlay", dim);
330	    set(
331	        "selection.background",
332	        hex_alpha(p.accent_fill, SELECTION_ALPHA),
333	    );
334	
335	    set("muted.background", hex(p.recessed));
336	    set("muted.foreground", hex(p.text_secondary));
337	    set("accent.background", hex(p.hover));
338	    set("accent.foreground", hex(p.text));
339	    set("accordion.background", hex(p.base));
340	    set("popover.background", hex(p.overlay));
341	    set("popover.foreground", hex(p.text));
342	    set("tiles.background", hex(p.base));
343	    set("group_box.background", hex(p.raised));
344	    set("group_box.foreground", hex(p.text));
345	    set("group_box.title.foreground", hex(p.text_secondary));
346	    set("description_list.label.background", hex(p.raised));
347	    set("description_list.label.foreground", hex(p.text_secondary));
348	    set("skeleton.background", hex(p.raised));
349	
350	    set("primary.background", hex(p.accent_fill));
351	    set("primary.hover.background", hex(fill_hover));
352	    set("primary.active.background", hex(fill_active));
353	    set("primary.foreground", hex(0xffffff));
354	    set("secondary.background", hex(p.raised));
355	    set("secondary.hover.background", hex(p.hover));
356	    set("secondary.active.background", hex(p.pressed));
357	    set("secondary.foreground", hex(p.text));
358	    set("button.background", hex(p.raised));
359	    set("button.hover.background", hex(p.hover));
360	    set("button.active.background", hex(p.pressed));
361	    set("button.foreground", hex(p.text));
362	    set("button.primary.background", hex(p.accent_fill));
363	    set("button.primary.hover.background", hex(fill_hover));
364	    set("button.primary.active.background", hex(fill_active));
365	    set("button.primary.foreground", hex(0xffffff));
366	
367	    for (name, hue) in [
368	        ("danger", p.error),
369	        ("success", p.success),
370	        ("warning", p.warning),
371	        ("info", p.accent),
372	    ] {
373	        set(&format!("{name}.background"), hex(hue));
374	        set(&format!("{name}.hover.background"), hex(hue));
375	        set(&format!("{name}.active.background"), hex(hue));
376	        set(&format!("{name}.foreground"), on_hue.clone());
377	    }
378	    set("link", hex(p.accent));
379	    set("link.hover", hex(p.accent));
380	    set("link.active", hex(p.accent));
381	
382	    set("list.background", hex(p.recessed));
383	    set("list.even.background", hex_alpha(p.recessed, 0));
384	    set("list.head.background", hex(p.raised));
385	    set("list.hover.background", hex(p.hover));
386	    set("list.active.background", hex(p.selected));
387	    set("list.active.border", hex(p.accent));
388	    set("table.background", hex(p.well));
389	    set("table.even.background", hex_alpha(p.well, 0));
390	    set("table.head.background", hex(p.raised));
391	    set("table.head.foreground", hex(p.text_secondary));
392	    set("table.foot.background", hex(p.raised));
393	    set("table.foot.foreground", hex(p.text_secondary));
394	    set("table.hover.background", hex(p.hover));
395	    set("table.active.background", hex(p.selected));
396	    set("table.active.border", hex(p.accent));
397	    set("table.row.border", hex(p.line));
398	
399	    set("tab.background", hex_alpha(p.raised, 0));
400	    set("tab.foreground", hex(p.text_secondary));
401	    set("tab.active.background", hex(p.base));
402	    set("tab.active.foreground", hex(p.text));
403	    set("tab_bar.background", hex(p.raised));
404	    set("tab_bar.segmented.background", hex(p.recessed));
405	    set("title_bar.background", hex(p.raised));
406	    set("title_bar.border", hex(p.line));
407	    set("status_bar.background", hex(p.raised));
408	    set("status_bar.border", hex(p.line));
409	    set("sidebar.background", hex(p.base));
410	    set("sidebar.foreground", hex(p.text));
411	    set("sidebar.border", hex(p.line));
412	    set("sidebar.accent.background", hex(p.hover));
413	    set("sidebar.accent.foreground", hex(p.text));
414	    set("sidebar.primary.background", hex(p.accent_fill));
415	    set("sidebar.primary.foreground", hex(0xffffff));
416	
417	    set("scrollbar.background", hex_alpha(p.recessed, 0));
418	    set("scrollbar.thumb.background", hex(p.pressed));
419	    set("scrollbar.thumb.hover.background", hex(p.hover));
420	    set("switch.background", hex(p.pressed));
421	    set("switch.thumb.background", hex(p.text));
422	    set("slider.background", hex(p.accent));
423	    set("slider.thumb.background", hex(p.text));
424	    set("progress.bar.background", hex(p.accent));
425	    set("drag.border", hex(p.accent));
426	    set("drop_target.background", hex_alpha(p.accent_fill, 0x40));
427	
428	    for (ix, hue) in [p.accent, p.cyan, p.purple, p.success, p.warning]
429	        .into_iter()
430	        .enumerate()
431	    {
432	        set(&format!("chart.{}", ix + 1), hex(hue));
433	    }
434	    set("chart_bullish", hex(p.success));
435	    set("chart_bearish", hex(p.error));
436	    for (name, hue) in [
437	        ("red", p.error),
438	        ("green", p.success),
439	        ("blue", p.accent),
440	        ("yellow", p.warning),
441	        ("magenta", p.purple),
442	        ("cyan", p.cyan),
443	    ] {
444	        set(&format!("base.{name}"), hex(hue));
445	        set(&format!("base.{name}.light"), hex(hue));
446	    }
447	
448	    // The editor sits in the well, keeping gpui-kit's syntax colours.
449	    let mut highlight = serde_json::to_value(&default.highlight).unwrap_or(Value::Null);
450	    if let Value::Object(style) = &mut highlight {
451	        for (key, value) in [
452	            ("editor.background", hex(p.well)),
453	            ("editor.foreground", hex(p.text)),
454	            ("editor.active_line.background", hex(p.recessed)),
455	            ("editor.line_number", hex(p.text_tertiary)),
456	            ("editor.active_line_number", hex(p.text)),
457	        ] {
458	            style.insert(key.to_string(), Value::String(value));
459	        }
460	    }
461	
462	    json!({
463	        "name": if dark { DARK_NAME } else { LIGHT_NAME },
464	        "mode": if dark { "dark" } else { "light" },
465	        "colors": colors,
466	        "highlight": highlight,
467	    })
468	}
