470	#[cfg(test)]
471	mod tests {
472	    use gpui_kit::component::{Theme, ThemeMode};
473	    use gpui_kit::{Hsla, TestAppContext};
474	
475	    use super::{Bevel, DARK, LIGHT, Palette, bevel_colors, bevel_edges, color};
476	
477	    /// The bevel is a pixel wide, lit along the top and left, shaded along
478	    /// the bottom and right, within the surface, with no edge over another;
479	    /// and faint on dark and light surfaces alike, its shade fainter still.
480	    #[test]
481	    fn the_bevel_is_faint_and_a_pixel_wide() {
482	        use gpui_kit::{Bounds, point, px, size};
483	        let surface = Bounds::new(point(px(10.), px(100.)), size(px(17.), px(60.)));
484	        for (palette, lightness) in [(&DARK, [0.18, 0.27]), (&LIGHT, [0.82, 0.91])] {
485	            let (light, shade) = bevel_colors(palette);
486	            let edges = bevel_edges(surface, Bevel::Raised, palette);
487	            // Pressed, the same edges, lit and shaded the other way round.
488	            let pressed = bevel_edges(surface, Bevel::Pressed, palette);
489	            for ((edge, color), (pressed_edge, pressed_color)) in edges.iter().zip(&pressed) {
490	                assert_eq!(edge, pressed_edge);
491	                assert_eq!(*pressed_color, if *color == light { shade } else { light });
492	            }
493	            assert_eq!(edges.len(), 4);
494	            let area: f32 = edges
495	                .iter()
496	                .map(|(edge, _)| edge.size.width.as_f32() * edge.size.height.as_f32())
497	                .sum();
498	            // Its outline, a pixel wide, counted once.
499	            assert_eq!(area, 2. * 17. + 2. * 58.);
500	            for (edge, color) in &edges {
501	                assert!(
502	                    edge.left() >= surface.left()
503	                        && edge.right() <= surface.right()
504	                        && edge.top() >= surface.top()
505	                        && edge.bottom() <= surface.bottom()
506	                );
507	                assert!(edge.size.width == px(1.) || edge.size.height == px(1.));
508	                if *color == light {
509	                    assert!(edge.top() == surface.top() || edge.left() == surface.left());
510	                } else {
511	                    assert!(edge.bottom() == surface.bottom() || edge.right() == surface.right());
512	                }
513	            }
514	            for l in lightness {
515	                let under = Hsla {
516	                    h: 0.,
517	                    s: 0.,
518	                    l,
519	                    a: 1.,
520	                };
521	                let lit = under.blend(light).l - l;
522	                let shaded = l - under.blend(shade).l;
523	                assert!(lit > 0. && lit < 0.1, "light {lit}");
524	                assert!(shaded > 0. && shaded < 0.03, "shade {shaded}");
525	                assert!(shaded < lit, "shade {shaded} over light {lit}");
526	            }
527	        }
528	        let tiny = Bounds::new(point(px(0.), px(0.)), size(px(1.), px(1.)));
529	        assert!(bevel_edges(tiny, Bevel::Raised, &DARK).is_empty());
530	    }
531	
532	    /// WCAG's contrast ratio between two opaque colours.
533	    fn contrast(a: u32, b: u32) -> f32 {
534	        let luminance = |c: u32| {
535	            let channel = |shift: u32| {
536	                let v = ((c >> shift) & 0xff) as f32 / 255.;
537	                if v <= 0.04045 {
538	                    v / 12.92
539	                } else {
540	                    ((v + 0.055) / 1.055).powf(2.4)
541	                }
542	            };
543	            0.2126 * channel(16) + 0.7152 * channel(8) + 0.0722 * channel(0)
544	        };
545	        let (a, b) = (luminance(a), luminance(b));
546	        (a.max(b) + 0.05) / (a.min(b) + 0.05)
547	    }
548	
549	    /// The contrast the theme promises, in both modes.
550	    #[test]
551	    fn both_modes_keep_their_contrast() {
552	        for (name, p) in [("dark", DARK), ("light", LIGHT)] {
553	            let Palette {
554	                base,
555	                recessed,
556	                well,
557	                overlay,
558	                ..
559	            } = p;
560	            for text in [p.text, p.text_secondary] {
561	                for surface in [base, recessed, well, overlay] {
562	                    assert!(
563	                        contrast(text, surface) >= 4.5,
564	                        "{name}: {text:06x} on {surface:06x}"
565	                    );
566	                }
567	            }
568	            for control in [p.raised, p.hover, p.pressed, p.selected] {
569	                assert!(
570	                    contrast(p.text, control) >= 4.,
571	                    "{name}: text on {control:06x}"
572	                );
573	            }
574	            for hue in [
575	                p.text_tertiary,
576	                p.success,
577	                p.warning,
578	                p.error,
579	                p.accent,
580	                p.orange,
581	            ] {
582	                assert!(contrast(hue, base) >= 3., "{name}: {hue:06x} on the base");
583	            }
584	            assert!(
585	                contrast(0xffffff, p.accent_fill) >= 4.5,
586	                "{name}: primary buttons"
587	            );
588	            let edge = contrast(p.edge, base);
589	            assert!((1.4..=1.7).contains(&edge), "{name}: edge {edge}");
590	            assert!(
591	                contrast(p.line, base) < edge,
592	                "{name}: lines are quieter than edges"
593	            );
594	        }
595	    }
596	
597	    /// The order of the surfaces holds in both modes: the base is the
598	    /// reference, pressed and selected are furthest from it that way in dark
599	    /// mode, hover furthest the raised way.
600	    #[test]
601	    fn surfaces_keep_their_order() {
602	        let lightness = |c: u32| Hsla::from(color(c)).l;
603	        let d = DARK;
604	        assert_eq!(d.base, 0x444444);
605	        assert!(lightness(d.well) < lightness(d.recessed));
606	        assert!(lightness(d.recessed) < lightness(d.base));
607	        assert!(lightness(d.base) < lightness(d.raised));
608	        assert!(lightness(d.raised) < lightness(d.hover));
609	        let l = LIGHT;
610	        assert!(lightness(l.well) > lightness(l.recessed));
611	        assert!(lightness(l.recessed) > lightness(l.base));
612	        assert!(lightness(l.selected) < lightness(l.pressed));
613	        assert!(lightness(l.pressed) < lightness(l.base));
614	    }
615	
616	    /// The darkest surface is a step past the ribbon's command area, away
617	    /// from its tab row, as far as the tab row is from it: #111111 in dark
618	    /// mode, a step lighter than the command area in light mode.
619	    #[test]
620	    fn the_darkest_surface_steps_past_the_ribbon() {
621	        assert_eq!(DARK.darkest, 0x111111);
622	        for (name, p) in [("dark", DARK), ("light", LIGHT)] {
623	            let channel = |c: u32| (c & 0xff) as i32;
624	            assert_eq!(
625	                channel(p.ribbon) - channel(p.darkest),
626	                channel(p.ribbon_tabs) - channel(p.ribbon),
627	                "{name}: the darkest surface isn't a step from the command area"
628	            );
629	            assert!(
630	                contrast(p.text, p.darkest) >= 4.5,
631	                "{name}: text on the darkest surface"
632	            );
633	        }
634	    }
635	
636	    /// gpui-kit's theme takes its colours from the palette in each mode.
637	    #[gpui_kit::test]
638	    fn gpui_kit_follows_the_palette(cx: &mut TestAppContext) {
639	        cx.update(|cx| {
640	            gpui_kit::init(cx);
641	            super::init(cx);
642	            for (mode, p) in [(ThemeMode::Dark, DARK), (ThemeMode::Light, LIGHT)] {
643	                Theme::change(mode, None, cx);
644	                let theme = Theme::global(cx);
645	                // gpui-kit lays some colours on at its own opacity.
646	                let same = |actual: Hsla, expected: u32, name: &str| {
647	                    let expected = color(expected);
648	                    assert!(
649	                        (actual.h - expected.h).abs() < 1e-3
650	                            && (actual.s - expected.s).abs() < 1e-3
651	                            && (actual.l - expected.l).abs() < 1e-3,
652	                        "{mode:?} {name}: {actual:?} isn't {expected:?}"
653	                    );
654	                };
655	                same(theme.background, p.base, "background");
656	                same(theme.foreground, p.text, "foreground");
657	                same(theme.muted_foreground, p.text_secondary, "muted_foreground");
658	                same(theme.border, p.edge, "border");
659	                same(theme.popover, p.overlay, "popover");
660	                same(theme.list_hover, p.hover, "list_hover");
661	                same(theme.list_active, p.selected, "list_active");
662	                same(theme.primary, p.accent_fill, "primary");
663	                same(theme.ring, p.accent, "ring");
664	                same(theme.danger, p.error, "danger");
665	                same(theme.success, p.success, "success");
666	                same(theme.warning, p.warning, "warning");
667	                same(theme.tab_bar, p.raised, "tab_bar");
668	                same(theme.red, p.error, "red");
669	                same(theme.blue, p.accent, "blue");
670	            }
671	        });
672	    }
673	}
