1	//! The user's light or dark mode choice, saved in the platform's per-user
2	//! config directory so it carries across launches and projects.
3	
4	use std::fs;
5	use std::path::{Path, PathBuf};
6	
7	use anyhow::{Context as _, Result, anyhow};
8	use gpui_kit::component::{Theme, ThemeMode};
9	use gpui_kit::*;
10	
11	/// Where the application keeps its per-user files, inside the config directory.
12	const APP_DIR: &str = "suspense";
13	const FILE_NAME: &str = "theme";
14	
15	/// Applies the saved choice to the theme, or follows the system's appearance
16	/// if none has been made.
17	pub fn apply(window: &mut Window, cx: &mut App) {
18	    match file().ok().and_then(|file| load(&file)) {
19	        Some(mode) => Theme::change(mode, Some(window), cx),
20	        None => Theme::sync_system_appearance(Some(window), cx),
21	    }
22	}
23	
24	/// Switches the theme to `mode` and saves it as the user's choice.
25	pub fn set(mode: ThemeMode, window: &mut Window, cx: &mut App) -> Result<()> {
26	    Theme::change(mode, Some(window), cx);
27	    save(mode, &file()?)
28	}
29	
30	fn file() -> Result<PathBuf> {
31	    let config_dir = dirs::config_dir().ok_or_else(|| anyhow!("no config directory"))?;
32	    Ok(config_dir.join(APP_DIR).join(FILE_NAME))
33	}
34	
35	fn load(file: &Path) -> Option<ThemeMode> {
36	    match fs::read_to_string(file).ok()?.trim() {
37	        "light" => Some(ThemeMode::Light),
38	        "dark" => Some(ThemeMode::Dark),
39	        _ => None,
40	    }
41	}
42	
43	fn save(mode: ThemeMode, file: &Path) -> Result<()> {
44	    if let Some(dir) = file.parent() {
45	        fs::create_dir_all(dir).with_context(|| format!("could not create {}", dir.display()))?;
46	    }
47	    fs::write(file, mode.name()).with_context(|| format!("could not save {}", file.display()))
48	}
49	
50	#[cfg(test)]
51	mod tests {
52	    use std::fs;
53	    use std::path::Path;
54	
55	    use gpui_kit::component::ThemeMode;
56	
57	    use super::{load, save};
58	
59	    #[test]
60	    fn saved_choice_loads_back() {
61	        let dir = Path::new(env!("CARGO_MANIFEST_DIR")).join("target/theme-preference-test");
62	        let file = dir.join("theme");
63	        fs::remove_dir_all(&dir).ok();
64	
65	        assert_eq!(load(&file), None);
66	        save(ThemeMode::Dark, &file).unwrap();
67	        assert_eq!(load(&file), Some(ThemeMode::Dark));
68	        save(ThemeMode::Light, &file).unwrap();
69	        assert_eq!(load(&file), Some(ThemeMode::Light));
70	    }
71	}
