30	/// Dark mode: a switch rather than a button, since it is on or off, taking the
31	/// room of a button of `size` but with no background, since it isn't one.
32	pub(super) fn dark_mode(size: CommandSize, cx: &mut Context<Ribbon>) -> AnyElement {
33	    let switch = Switch::new("dark-mode")
34	        .label("Dark mode")
35	        .checked(cx.theme().is_dark())
36	        .on_click(|dark, window, cx| set_dark_mode(*dark, window, cx));
