64	/// Switches between light and dark mode, saving the choice.
65	pub fn set_dark_mode(dark: bool, window: &mut Window, cx: &mut App) {
66	    let mode = if dark {
67	        gpui_kit::component::ThemeMode::Dark
68	    } else {
69	        gpui_kit::component::ThemeMode::Light
70	    };
