48	/// The height of the row of tabs, which the collapsed ribbon's row keeps.
49	const TAB_ROW_HEIGHT: Pixels = px(32.);
50	
51	/// The room either side of a tab's label, which is all a tab is.
52	const TAB_PADDING: Pixels = px(8.);
53	
54	/// The padding around the commands, on every side.
55	const BODY_PADDING: Pixels = px(8.);
56	
57	/// The gap between one command and the next, across and down, and between a
58	/// group's buttons and the divider beside them.
59	const GAP: Pixels = px(4.);
60	
61	/// How wide the divider between two groups is.
62	const DIVIDER_WIDTH: Pixels = px(4.);
63	
64	/// A slim button's height.
65	const SLIM_HEIGHT: Pixels = px(27.);
66	
67	/// A small button's height, in the collapsed ribbon's row.
68	const SMALL_HEIGHT: Pixels = px(22.);
69	
70	/// Slim buttons stacked in one column, at most.
71	const SLIM_STACK: usize = 2;
72	
73	/// How tall a column of `slim` slim buttons is, with the gaps between them.
74	fn stacked(slim: usize) -> Pixels {
75	    SLIM_HEIGHT * slim as f32 + GAP * (slim as f32 - 1.)
76	}
77	
78	/// A full button is exactly two slim buttons tall, however much its icon and
79	/// label would take.
80	fn full_height() -> Pixels {
81	    stacked(SLIM_STACK)
82	}
