335	            format!("{count} things running").into()
336	        };
337	        let list = self.jobs_open.then(|| {
338	            let rows = self.jobs.iter().enumerate().map(|(ix, job)| {
339	                let (kind, project) = (job.kind, job.project.clone());
340	                let row = h_flex()
341	                    .id(("ribbon-job", ix))
342	                    .gap_2()
343	                    .px_3()
344	                    .py_1p5()
345	                    .rounded(theme.radius)
346	                    .cursor_pointer()
347	                    .hover(|row| row.bg(theme.list_hover))
348	                    .on_click(cx.listener(move |this, _, _, cx| {
349	                        this.jobs_open = false;
350	                        cx.emit(RevealJob(kind, project.clone()));
351	                        cx.notify();
352	                    }))
353	                    .child(gpui_kit::component::spinner::Spinner::new().small())
354	                    .child(div().flex_none().font_medium().child(job.title.clone()))
355	                    .children(job.detail.clone().map(|detail| {
356	                        div()
357	                            .flex_1()
358	                            .min_w_0()
359	                            .truncate()
360	                            .text_color(theme.muted_foreground)
361	                            .child(detail)
362	                    }));
363	                // Lets UI tests find the row; inert in normal builds.
364	                gpui_kit::TestSupportExt::test_support(row)
365	            });
366	            let list = v_flex()
367	                .id("ribbon-jobs")
368	                .w(px(360.))
369	                .mt(px(28.))
370	                .p_1()
371	                .rounded(theme.radius)
372	                .border_1()
373	                .border_color(theme.border)
374	                .bg(theme.popover)
375	                .shadow_md()
376	                .occlude()
377	                .on_mouse_down_out(cx.listener(|this, _, _, cx| this.close_jobs(cx)))
378	                .children(rows);
379	            // Lets UI tests find the list; inert in normal builds.
380	            deferred(
381	                anchored()
382	                    .snap_to_window()
383	                    .child(gpui_kit::TestSupportExt::test_support(list)),
384	            )
385	            .with_priority(2)
386	        });
387	        let spinner = h_flex()
388	            .id("ribbon-activity")
389	            .flex_none()
390	            .gap_1()
391	            .px_1()
392	            .py_0p5()
393	            .rounded(theme.radius)
394	            .cursor_pointer()
395	            .hover(|spinner| spinner.bg(theme.list_hover))
396	            .tooltip(move |window, cx| {
397	                gpui_kit::component::tooltip::Tooltip::new(tooltip.clone()).build(window, cx)
398	            })
399	            .on_click(cx.listener(|this, _, _, cx| {
400	                this.jobs_open = !this.jobs_open;
401	                cx.notify();
402	            }))
403	            .child(gpui_kit::component::spinner::Spinner::new().small())
404	            .when(count > 1, |spinner| {
405	                spinner.child(
406	                    div()
407	                        .text_xs()
408	                        .text_color(theme.muted_foreground)
409	                        .child(count.to_string()),
410	                )
411	            })
412	            .children(list);
413	        // Lets UI tests find the spinner; inert in normal builds.
414	        Some(gpui_kit::TestSupportExt::test_support(spinner).into_any_element())
415	    }
