431	    /// A tab was clicked: it opens alone, and a double-click collapses the
432	    /// ribbon; with `add`, from Ctrl/Cmd+click, it opens alongside the others,
433	    /// or closes if it was open, unless it is the only one. (Collapsed, there
434	    /// are no tabs to click.)
435	    pub(crate) fn tab_clicked(
436	        &mut self,
437	        tab: RibbonTab,
438	        clicks: usize,
439	        add: bool,
440	        cx: &mut Context<Self>,
441	    ) {
442	        if add {
443	            self.open_tabs = toggle_open(&self.open_tabs, tab);
444	        } else {
445	            self.open_tabs = vec![tab];
446	            if clicks >= 2 && !self.collapsed {
447	                self.toggle_collapsed(cx);
448	            }
449	        }
450	        cx.notify();
451	    }
