454	    /// alone, as a click does, expanding the ribbon if it is collapsed. An
455	    /// index past the last tab does nothing.
456	    pub fn show_tab_at(&mut self, ix: usize, cx: &mut Context<Self>) {
457	        let Some(&tab) = RibbonTab::ALL.get(ix) else {
458	            return;
459	        };
460	        if self.collapsed {
461	            self.toggle_collapsed(cx);
462	        }
463	        self.select_tab(tab, cx);
464	    }
