478	impl Ribbon {
479	    /// `command`'s control: large, with its icon above its label, or small,
480	    /// with its icon beside it, for the collapsed ribbon.
481	    fn render_command(
482	        &self,
483	        command: Command,
484	        size: CommandSize,
485	        cx: &mut Context<Self>,
486	    ) -> AnyElement {
487	        let colors = command_colors(cx);
488	        let rest = command_shades(cx).0;
489	        let button_with = |id: ElementId, icon: IconName, label: SharedString| {
490	            // gpui-kit keeps only a fifth of a custom button's resting colour,
491	            // so the colour is given to the button itself; its hover and
492	            // pressed colours are taken whole.
493	            let button = Button::new(id)
494	                .custom(colors)
495	                .rounded(ButtonRounded::None)
496	                .bg(rest);
497	            match size {
498	                // Slim fills its column; small, in a row, never stretches.
499	                CommandSize::Slim | CommandSize::Small => button
500	                    .small()
501	                    .map(|button| match size {
502	                        CommandSize::Small => button.h(SMALL_HEIGHT).flex_none(),
503	                        _ => button.h(SLIM_HEIGHT).w_full(),
504	                    })
505	                    .px_2()
506	                    .icon(Icon::new(icon).with_size(Size::Small))
507	                    .label(label),
508	                // Its small icon centred above its label, the pair centred in
509	                // the two slim buttons' height its column gives it, rather
510	                // than the height a button takes by default.
511	                CommandSize::Full => button.flex_none().h_auto().px_2().child(
512	                    v_flex()
513	                        .items_center()
514	                        .gap_1p5()
515	                        .child(Icon::new(icon).with_size(Size::Small))
516	                        .child(div().text_sm().child(label)),
517	                ),
518	            }
519	        };
520	        let button = |id: &'static str, icon: IconName, label: SharedString| {
521	            button_with(id.into(), icon, label)
522	        };
523	        match command {
524	            Command::FindHowToRun => code_tab::find_how_to_run(&button_with, cx),
525	            Command::FindRunAgain => code_tab::find_again(&button_with, cx),
526	            Command::RunTarget(ix) => code_tab::run_target(ix, &button_with, cx),
527	            Command::NewProject => project_tab::new_project(button),
528	            Command::OpenProject => project_tab::open_project(button),
529	            Command::BuildSpec => spec_tab::build_spec(self, button, cx),
530	            Command::NewScope => spec_tab::new_scope(button, cx),
531	            Command::NewConcept => spec_tab::new_concept(button, cx),
532	            Command::NewShape => spec_tab::new_shape(button, cx),
533	            Command::NewInstruction => spec_tab::new_instruction(button, cx),
534	            Command::AnalyzeDivergence => spec_tab::analyze_divergence(button, cx),
535	            Command::ViewDivergenceReports => spec_tab::view_divergence_reports(button, cx),
536	            Command::GenerateSkills => spec_tab::generate_skills(button, cx),
537	            Command::Rescope => spec_tab::rescope(button, cx),
538	            Command::DarkMode => application_tab::dark_mode(size, cx),
539	            Command::Settings => application_tab::settings(button),
540	        }
541	    }
542	}
