547	/// A container at either end of the bar: what it holds side by side,
548	/// vertically centred, with no gap between them or padding around them,
549	/// only as wide as they are; nothing at all while it holds nothing. As tall
550	/// as the tab row, which the collapsed ribbon's row keeps, so it is the same
551	/// height, its contents in the same place, whether the ribbon is expanded or
552	/// collapsed. Lets UI tests find it; inert in normal builds.
553	fn container(id: &'static str, items: Vec<AnyElement>) -> Option<AnyElement> {
554	    (!items.is_empty()).then(|| {
