564	impl Render for Ribbon {
565	    fn render(&mut self, _: &mut Window, cx: &mut Context<Self>) -> impl IntoElement {
566	        let theme = cx.theme();
567	        let (border, muted, foreground) =
568	            (theme.border, theme.muted_foreground, theme.foreground);
569	        let (area, tab_row) = ribbon_colors(cx);
570	
571	        // Square, and the same size expanded or collapsed: only the way it
572	        // points changes.
573	        let collapse = Button::new("ribbon-collapse")
574	            .ghost()
575	            .xsmall()
576	            .flex_none()
577	            .size(CHEVRON_SIZE)
578	            .icon(if self.collapsed {
579	                IconName::ChevronDown
580	            } else {
581	                IconName::ChevronUp
582	            })
583	            .tooltip_with_action(
584	                if self.collapsed {
585	                    "Expand the ribbon"
586	                } else {
587	                    "Collapse the ribbon to its primary commands"
588	                },
589	                &ToggleRibbon,
590	                None,
591	            )
592	            .on_click(cx.listener(|this, _, _, cx| this.toggle_collapsed(cx)));
593	        let ribbon = div()
594	            .id("ribbon")
595	            .flex()
596	            .flex_col()
597	            .border_b_1()
598	            .border_color(border);
599	
600	        if self.collapsed {
601	            // No tabs: every primary command, small, in one row, a divider
602	            // between one tab's commands and the next, led by the project's
603	            // name, as beside the tabs.
604	            let mut row = Vec::new();
605	            let mut last_tab = None;
606	            let primary: Vec<_> = RibbonTab::ALL
607	                .into_iter()
608	                .flat_map(|tab| {
609	                    tab.commands(cx)
610	                        .into_iter()
611	                        .filter(|place| place.primary)
612	                        .map(move |place| (tab, place))
613	                })
614	                .collect();
615	            for (tab, place) in primary {
616	                if last_tab.is_some_and(|last| last != tab) {
617	                    // Centred like the controls, rather than stretched.
618	                    row.push(
619	                        div()
620	                            .flex_none()
621	                            .w_px()
622	                            .h(px(16.))
623	                            .bg(border)
624	                            .into_any_element(),
625	                    );
626	                }
627	                last_tab = Some(tab);
628	                row.push(self.render_command(place.command, CommandSize::Small, cx));
629	            }
630	            // Lets UI tests find the row; inert in normal builds. The
631	            // indicator and the chevron after it stay put; what follows them
632	            // scrolls sideways when it's wider than the room left. It holds
633	            // commands, so it is the command area's colour, and its buttons
634	            // stand apart from it as they do there.
635	            return ribbon.child(gpui_kit::TestSupportExt::test_support(
636	                h_flex()
637	                    .id("ribbon-primary")
638	                    // As tall as the tab row, so collapsing moves nothing.
639	                    .h(TAB_ROW_HEIGHT)
640	                    .items_stretch()
641	                    .bg(area)
642	                    .children(self.render_left(collapse, cx))
643	                    .child(gpui_kit::TestSupportExt::test_support(
644	                        h_flex()
645	                            .id("ribbon-primary-commands")
646	                            .flex_1()
647	                            .min_w_0()
648	                            .overflow_x_scroll()
649	                            // Every control is vertically centred in the row.
650	                            .items_center()
651	                            .gap_2()
652	                            .px_2()
653	                            .children(row),
654	                    ))
655	                    .children(self.render_right()),
656	            ));
657	        }
658	
659	        // Flat tabs, each only its label with room either side, and no
660	        // border, corner, or line anywhere. A closed tab has no background of
661	        // its own, showing the tab row's; an open one takes the command
662	        // area's, so it and the commands beneath read as one piece. Each
663	        // handles its own clicks, so a double-click can be told apart: it
664	        // collapses the ribbon.
665	        let hover = tab_hover(cx);
666	        let tabs = RibbonTab::ALL.into_iter().enumerate().map(|(ix, tab)| {
667	            let open = self.open_tabs.contains(&tab);
668	            let tint = tab
669	                .mode()
670	                .map(|mode| crate::chat_input::mode_tint(mode, cx));
671	            // A tab with a mode's colour shows it in its label while closed,
672	            // the hue at full strength; open, its label is the tab's own
673	            // colour. The label is the same text in the same place either
674	            // way, only its colour changing, so it never moves.
675	            let label = match tint {
676	                Some(tint) if !open => Hsla { a: 1., ..tint },
677	                _ => foreground,
678	            };
679	            // Lets UI tests find the tab; inert in normal builds.
680	            gpui_kit::TestSupportExt::test_support(div().id(("ribbon-tab", ix)))
681	                .relative()
682	                .flex()
683	                .flex_none()
684	                .items_center()
685	                .h_full()
686	                .px(TAB_PADDING)
687	                .text_sm()
688	                .whitespace_nowrap()
689	                .cursor_pointer()
690	                .role(Role::Tab)
691	                .aria_label(tab.label())
692	                .aria_selected(open)
693	                .when(open, |this| this.bg(area))
694	                .when(!open, |this| this.hover(|this| this.bg(hover)))
695	                // An open Code or Spec tab is tinted as the chat input's tab
696	                // of that mode is: the tint laid over it, beneath its label,
697	                // taking no room, so the tab keeps its own size and its label
698	                // stays put.
699	                .when_some(tint.filter(|_| open), |this, tint| {
700	                    this.child(div().absolute().inset_0().bg(tint))
701	                })
702	                .child(div().relative().text_color(label).child(tab.label()))
703	                .on_click(cx.listener(move |this, event: &ClickEvent, _, cx| {
704	                    this.tab_clicked(tab, event.click_count(), event.modifiers().secondary(), cx)
705	                }))
706	        })
707	            .collect::<Vec<_>>();
708	        // The left container, holding the open project's name, the chevron,
709	        // and the activity spinner, left of the tabs, and the right container
710	        // after them, all on the tab row's own background.
711	        let tab_bar = h_flex()
712	            .w_full()
713	            .h(TAB_ROW_HEIGHT)
714	            .overflow_hidden()
715	            .items_start()
716	            .bg(tab_row)
717	            .children(self.render_left(collapse, cx))
718	            .child(
719	                h_flex()
720	                    .id("ribbon-tabs")
721	                    .role(Role::TabList)
722	                    .flex_1()
723	                    .min_w_0()
724	                    .h_full()
725	                    .children(tabs),
726	            )
727	            .children(self.render_right());
728	
729	        // With a Code or Spec tab open alone, the body is tinted as the chat
730	        // input's is for that mode.
731	        let body_tint = match self.open_tabs.as_slice() {
732	            [tab] => tab
733	                .mode()
734	                .map(|mode| crate::chat_input::mode_tint(mode, cx)),
735	            _ => None,
736	        };
737	
738	        // Each open tab's commands, gathered into their groups in order.
739	        let mut groups: Vec<(&'static str, Vec<(CommandSize, AnyElement)>)> = Vec::new();
740	        for tab in &self.open_tabs {
741	            let start = groups.len();
742	            for place in tab.commands(cx) {
743	                let element = (
744	                    place.size,
745	                    self.render_command(place.command, place.size, cx),
746	                );
747	                match groups[start..].last_mut() {
748	                    Some((group, commands)) if *group == place.group => commands.push(element),
749	                    _ => groups.push((place.group, vec![element])),
750	                }
751	            }
752	        }
753	        // A divider between one group and the next, within a tab or between
754	        // tabs alike, named for the group it starts.
755	        let mut row = Vec::new();
756	        for (ix, (label, commands)) in groups.into_iter().enumerate() {
757	            if ix > 0 {
758	                row.push(divider(ix, label, tab_row));
759	            }
760	            row.push(group(label, commands));
761	        }
762	        if row.is_empty() {
763	            row.push(
764	                div()
765	                    .flex()
766	                    .items_center()
767	                    .text_sm()
768	                    .text_color(muted)
769	                    .child("No commands yet")
770	                    .into_any_element(),
771	            );
772	        }
773	
774	        // Lets UI tests find the tabs and the commands; inert in normal builds.
775	        let tab_bar =
776	            gpui_kit::TestSupportExt::test_support(div().id("ribbon-tabs-row").child(tab_bar));
777	        ribbon
778	            .child(tab_bar)
779	            .child(gpui_kit::TestSupportExt::test_support(
780	                div()
781	                    .id("ribbon-controls")
782	                    .flex()
783	                    .flex_row()
784	                    // Scrolls sideways when the open tabs' groups are wider
785	                    // than the window.
786	                    .overflow_x_scroll()
787	                    // The dividers run the buttons' full height.
788	                    .items_stretch()
789	                    .p(BODY_PADDING)
790	                    .gap(GAP)
791	                    // No taller than its commands need.
792	                    .flex_none()
793	                    // With the Code or Spec tab open alone, its body is tinted
794	                    // as the chat input's body is for its mode.
795	                    .bg(body_tint.map_or(area, |tint| area.blend(tint)))
796	                    .children(row),
797	            ))
798	    }
799	}
