801	/// The open tabs once `tab` is Ctrl/Cmd+clicked: opened alongside `open`, or
802	/// closed if it was open and isn't the only one; always in the order of the
803	/// tabs.
804	pub fn toggle_open(open: &[RibbonTab], tab: RibbonTab) -> Vec<RibbonTab> {
805	    let was_open = open.contains(&tab);
806	    if was_open && open.len() == 1 {
807	        return open.to_vec();
808	    }
809	    RibbonTab::ALL
810	        .into_iter()
811	        .filter(|candidate| {
812	            if *candidate == tab {
813	                !was_open
814	            } else {
815	                open.contains(candidate)
816	            }
817	        })
818	        .collect()
819	}
