821	/// A group of related commands, named for assistive technology though not
822	/// titled on screen.
823	fn group(label: &'static str, commands: Vec<(CommandSize, AnyElement)>) -> AnyElement {
824	    // Full buttons stand alone; slim ones side by side stack down, two to a
825	    // column, top aligned.
826	    let mut columns: Vec<AnyElement> = Vec::new();
827	    let mut stack: Vec<AnyElement> = Vec::new();
828	    let flush = |stack: &mut Vec<AnyElement>, columns: &mut Vec<AnyElement>| {
829	        if !stack.is_empty() {
830	            columns.push(
831	                v_flex()
832	                    .flex_none()
833	                    .gap(GAP)
834	                    .children(stack.drain(..))
835	                    .into_any_element(),
836	            );
837	        }
838	    };
839	    for (size, element) in commands {
840	        match size {
841	            CommandSize::Full => {
842	                flush(&mut stack, &mut columns);
843	                // Exactly two slim buttons tall, whatever its content; the
844	                // button itself fills that.
845	                columns.push(
846	                    h_flex()
847	                        .flex_none()
848	                        .items_stretch()
849	                        .overflow_hidden()
850	                        .h(full_height())
851	                        .child(element)
852	                        .into_any_element(),
853	                );
854	            }
855	            CommandSize::Slim | CommandSize::Small => {
856	                if stack.len() == SLIM_STACK {
857	                    flush(&mut stack, &mut columns);
858	                }
859	                stack.push(element);
860	            }
861	        }
862	    }
863	    flush(&mut stack, &mut columns);
864	    // Each command takes the height it needs, a full button two slim buttons,
865	    // all from the top. Lets UI tests find the group; inert in normal builds.
866	    gpui_kit::TestSupportExt::test_support(h_flex().id(label))
867	        .flex_none()
868	        .items_start()
869	        .gap(GAP)
870	        .role(Role::Group)
871	        .aria_label(label)
872	        .children(columns)
873	        .into_any_element()
874	}
