876	/// The divider starting the group `label`, the `ix`th group of the open tabs:
877	/// a bar in the tab row's colour, as tall as the buttons, its ends softly
878	/// rounded, with the group's name as its tooltip. Lets UI tests find it;
879	/// inert in normal builds.
880	fn divider(ix: usize, label: &'static str, color: Hsla) -> AnyElement {
881	    gpui_kit::TestSupportExt::test_support(div().id(("ribbon-divider", ix)))
882	        .flex_none()
883	        .w(DIVIDER_WIDTH)
884	        .rounded(DIVIDER_WIDTH / 2.)
885	        .bg(color)
886	        .role(Role::Splitter)
887	        .aria_label(label)
888	        .tooltip(move |window, cx| {
889	            gpui_kit::component::tooltip::Tooltip::new(label).build(window, cx)
890	        })
891	        .into_any_element()
892	}
