903	/// A closed tab under the pointer: a faint step lighter in dark mode, darker
904	/// in light mode, laid over the tab row.
905	fn tab_hover(cx: &App) -> Hsla {
906	    if cx.theme().is_dark() {
907	        gpui_kit::white().opacity(0.06)
908	    } else {
909	        gpui_kit::black().opacity(0.06)
910	    }
911	}
