913	/// A ribbon command's background at rest, hovered, and pressed, laid over the
914	/// command area. At rest in dark mode, white laid just far enough over the
915	/// area to reach the base, #444444 on #222222; in light mode, not quite half
916	/// way.
917	pub(crate) fn command_shades(cx: &App) -> (Hsla, Hsla, Hsla) {
